135				slog.String("ref", refName.String()), slog.String("error", err.Error()))
136			return
137		}
138		if err := q.Enqueue(refName); err != nil {
139			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
140				slog.String("ref", refName.String()), slog.String("error", err.Error()))
