1645	// committed checkpoint. Uses replace semantics: the full session transcript is
1646	// written, replacing whatever was stored at initial condensation time.
1647	//
1648	// This is called at stop time to finalize all checkpoints from the current turn
1649	// with the complete session transcript (from prompt to stop event).
1650	//
1651	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1652	func (s *GitStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
1653		if err := ctx.Err(); err != nil {
1654			return err //nolint:wrapcheck // Propagating context cancellation
1655		}
1656		if opts.CheckpointID.IsEmpty() {
1657			return errors.New("invalid update options: checkpoint ID is required")
1658		}
1659	
1660		// Backfills require the branch to exist; a miss must not create it.
1661		if err := s.requireSessionsBranch(); err != nil {
1662			return err
1663		}
1664	
1665		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1666		commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
1667		_, err := RunRefTransaction(ctx, s.repo, s.refs.Primary, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
1668			if parentHash.IsZero() {
1669				return plumbing.ZeroHash, false, ErrCheckpointNotFound
1670			}
1671			rootTreeHash, err := s.rootTreeHashAt(parentHash)
1672			if err != nil {
1673				return plumbing.ZeroHash, false, err
1674			}
1675			existing, err := s.subtreeObjAt(rootTreeHash, opts.CheckpointID.Path())
1676			if err != nil {
1677				return plumbing.ZeroHash, false, err
1678			}
1679			checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, opts.CheckpointID.Path()+"/")
1680			if err != nil {
1681				return plumbing.ZeroHash, false, err
1682			}
1683			newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, checkpointSubtree)
1684			if err != nil {
