 556	// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
 557	// Returns the absolute file paths from the git tree root for the sessions map.
 558	func (s *treeWriter) writeSessionToSubdirectory(ctx context.Context, opts WriteOptions, sessionDir string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
 559		filePaths := SessionFilePaths{}
 560	
 561		// Clear any existing entries under this session dir so stale files from a
 562		// previous write (e.g. prompt.txt) don't persist on overwrite. Match on the
 563		// dir plus "/" so a sibling session (e.g. "10") isn't caught by "1".
 564		for key := range entries {
 565			if strings.HasPrefix(key, sessionDir+"/") {
 566				delete(entries, key)
 567			}
 568		}
 569	
 570		// Write transcript. Transcript points at full.jsonl (CLI
 571		// rewind/resume/explain read it by filename); the compact transcript.jsonl,
 572		// when written, is also pushed and pointed at by CompactTranscript.
 573		wroteTranscript, compactTranscriptStart, err := s.writeTranscript(ctx, opts, sessionDir, entries)
 574		if err != nil {
 575			return filePaths, err
 576		}
 577		if wroteTranscript {
 578			filePaths.Transcript = "/" + checkpointSubtreePath(sessionDir, paths.TranscriptFileName)
 579			filePaths.ContentHash = "/" + checkpointSubtreePath(sessionDir, paths.ContentHashFileName)
 580			// Point at the compact transcript only when it was actually written
 581			// (best-effort), deriving from the tree entry so the path can't dangle.
 582			if _, ok := entries[checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)]; ok {
 583				filePaths.CompactTranscript = "/" + checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)
 584			}
 585		}
 586	
 587		// Write externalized image assets (raw binary blobs + manifest), when present.
 588		manifestPath, err := s.writeAssets(opts.Assets, sessionDir, entries)
 589		if err != nil {
 590			return filePaths, err
 591		}
 592		filePaths.AssetsManifest = manifestPath
 593	
 594		// Write prompts via the regex-only pipeline. OPF runs only in the
 595		// pre-push rewrite path (manual_commit_opf_rewrite.go).
 596		if len(opts.Prompts) > 0 {
 597			promptContent := RedactedJoinedPrompts(opts.Prompts)
 598			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
 599			if err != nil {
 600				return filePaths, err
 601			}
 602			promptPath := checkpointSubtreePath(sessionDir, paths.PromptFileName)
 603			entries[promptPath] = object.TreeEntry{
 604				Name: promptPath,
 605				Mode: filemode.Regular,
 606				Hash: blobHash,
 607			}
 608			filePaths.Prompt = "/" + promptPath
 609		}
 610	
 611		// The write boundary dedupes as a last line of defense, but duplicates
 612		// reaching it mean an upstream producer skipped mergeFilesTouched — warn
 613		// so that producer can be found rather than silently masked.
 614		filesTouched := NormalizeFilesTouched(opts.FilesTouched)
 615		if len(filesTouched) < len(opts.FilesTouched) {
 616			logging.Warn(logging.WithComponent(ctx, "checkpoint"),
 617				"files_touched reached the write boundary with duplicates",
 618				slog.String("session_id", opts.SessionID),
 619				slog.Int("reported", len(opts.FilesTouched)),
 620				slog.Int("unique", len(filesTouched)),
 621			)
 622		}
 623	
 624		// Write session-level metadata.json (Metadata with all fields including initial_attribution)
 625		sessionMetadata := Metadata{
 626			CheckpointID:                opts.CheckpointID,
 627			SessionID:                   opts.SessionID,
 628			Strategy:                    opts.Strategy,
 629			CreatedAt:                   checkpointCreatedAt(opts),
 630			Branch:                      opts.Branch,
 631			CommitSHA:                   opts.CommitSHA,
 632			CheckpointsCount:            opts.CheckpointsCount,
 633			SaveStepCount:               opts.SaveStepCount,
 634			FilesTouched:                filesTouched,
 635			Agent:                       opts.Agent,
 636			Model:                       opts.Model,
 637			TurnID:                      opts.TurnID,
 638			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
 639			CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
 640			TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
 641			CompactTranscriptStart:      compactTranscriptStart,
 642			TokenUsage:                  opts.TokenUsage,
 643			SkillEventsVersion:          skillEventsVersion(opts.SkillEvents),
 644			SkillEvents:                 opts.SkillEvents,
 645			SessionMetrics:              opts.SessionMetrics,
 646			Attribution:                 opts.Attribution,
 647			PromptAttributions:          opts.PromptAttributionsJSON,
 648			Summary:                     RedactSummary(opts.Summary),
 649			CLIVersion:                  versioninfo.Version,
 650			Kind:                        opts.Kind,
 651			ReviewSkills:                opts.ReviewSkills,
 652			ReviewPrompt:                opts.ReviewPrompt,
 653			InvestigateRunID:            opts.InvestigateRunID,
 654			InvestigateTopic:            opts.InvestigateTopic,
 655		}
 656	
 657		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
 658		if err != nil {
 659			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
 660		}
 661		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 662		if err != nil {
 663			return filePaths, err
 664		}
 665		sessionMetadataPath := checkpointSubtreePath(sessionDir, paths.MetadataFileName)
 666		entries[sessionMetadataPath] = object.TreeEntry{
 667			Name: sessionMetadataPath,
 668			Mode: filemode.Regular,
 669			Hash: metadataHash,
 670		}
 671		filePaths.Metadata = "/" + sessionMetadataPath
 672	
 673		return filePaths, nil
 674	}
