 283	
 284		// Find session index matching opts.SessionID
 285		sessionIndex := -1
 286		var sessionMeta *Metadata
 287		for i := range len(checkpointSummary.Sessions) {
 288			metaPath := checkpointSubtreePath(basePath, strconv.Itoa(i), paths.MetadataFileName)
 289			if metaEntry, metaExists := entries[metaPath]; metaExists {
 290				meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
 291				if metaErr == nil && meta.SessionID == opts.SessionID {
 292					sessionIndex = i
