 884		}
 885		defer reader.Close()
 886	
 887		var result T
 888		if err := json.NewDecoder(reader).Decode(&result); err != nil {
 889			return nil, fmt.Errorf("failed to decode: %w", err)
 890		}
 891	
 892		return &result, nil
 893	}
