440		info := cp.CheckpointInfo{
441			CheckpointID:     sc.Summary.CheckpointID,
442			CheckpointsCount: sc.Summary.CheckpointsCount,
443			FilesTouched:     sc.Summary.FilesTouched,
444			SessionCount:     len(sc.Sessions),
445		}
446		if n := len(sc.Sessions); n > 0 {
447			last := sc.Sessions[n-1]
448			info.SessionID = last.SessionID
449			info.CreatedAt = last.Metadata.CreatedAt
450			info.Agent = last.Metadata.Agent
451			info.IsTask = last.Metadata.IsTask
452			info.ToolUseID = last.Metadata.ToolUseID
453		}
454		info.SessionIDs = make([]string, 0, len(sc.Sessions))
455		for i := range sc.Sessions {
456			info.SessionIDs = append(info.SessionIDs, sc.Sessions[i].SessionID)
457		}
458		return info
459	}

