166	func (s *treeWriter) prepareBatchSessions(ctx context.Context, req BatchSessions) (*preparedBatchSessions, error) {
167		canonical, err := CanonicalizeBatchSessions(req)
168		if err != nil {
169			return nil, err
170		}
430	
431		rootEntries := make(map[string]object.TreeEntry)
432		if existing != nil {
433			for _, entry := range existing.Entries {
434				stats.RootEntriesVisited++
435				rootEntries[entry.Name] = entry
436			}
437		}
438	
439		var existingSummary *CheckpointSummary
440		if entry, ok := rootEntries[paths.MetadataFileName]; ok {
441			var err error
442			existingSummary, err = s.readSummaryFromBlob(entry.Hash)
443			if err != nil {
444				return plumbing.ZeroHash, stats, fmt.Errorf("read existing checkpoint summary: %w", err)
445			}
446			if existingSummary.CheckpointID != prepared.request.CheckpointID {
447				return plumbing.ZeroHash, stats, fmt.Errorf("existing checkpoint summary ID %s does not match batch checkpoint ID %s", existingSummary.CheckpointID, prepared.request.CheckpointID)
448			}
449		} else if existing != nil && len(existing.Entries) != 0 {
450			return plumbing.ZeroHash, stats, errors.New("existing checkpoint tree has no root metadata")
451		}
452	
453		var sessionPaths []SessionFilePaths
454		finalByID := make(map[string]finalBatchSession)
455		indexBySession := make(map[string]int)
456		if existingSummary != nil {
457			sessionPaths = append([]SessionFilePaths(nil), existingSummary.Sessions...)
458			for index := range existingSummary.Sessions {
459				entry, ok := rootEntries[strconv.Itoa(index)]
460				if !ok || entry.Mode != filemode.Dir {
461					return plumbing.ZeroHash, stats, fmt.Errorf("existing session %d subtree is missing", index)
462				}
463				metadata, err := s.readSessionMetadataFromSubtree(entry.Hash, &stats)
464				if err != nil {
465					return plumbing.ZeroHash, stats, fmt.Errorf("read existing session %d metadata: %w", index, err)
466				}
467				if _, duplicate := finalByID[metadata.SessionID]; duplicate {
468					return plumbing.ZeroHash, stats, fmt.Errorf("existing checkpoint repeats session ID %q", metadata.SessionID)
469				}
470				finalByID[metadata.SessionID] = finalSessionFromMetadata(metadata)
471				indexBySession[metadata.SessionID] = index
472			}
473		}
474	
475		nextSessionIndex := len(sessionPaths)
476		for _, incoming := range prepared.sessions {
477			index, exists := indexBySession[incoming.opts.SessionID]
478			if !exists {
479				index = nextSessionIndex
480				nextSessionIndex++
481				indexBySession[incoming.opts.SessionID] = index
482				sessionPaths = append(sessionPaths, SessionFilePaths{})
483			}
484			rootEntries[strconv.Itoa(index)] = object.TreeEntry{
485				Name: strconv.Itoa(index), Mode: filemode.Dir, Hash: incoming.treeHash,
486			}
487			sessionPaths[index] = qualifySessionFilePaths(basePath, index, incoming.filePaths)
488			finalByID[incoming.opts.SessionID] = finalBatchSession{
489				metadata:  incoming.metadata,
490				hasReview: incoming.opts.HasReview || incoming.metadata.Kind == checkpointKindAgentReview,
491				hasInvestigation: incoming.opts.HasInvestigation ||
492					incoming.metadata.Kind == checkpointKindAgentInvestigate,
493				imported: incoming.opts.Kind == checkpointKindImported,
494			}
495		}
496	
497		if len(prepared.tasks) > 0 {
498			tasksHash, err := s.mergePreparedTasks(rootEntries, prepared.tasks, &stats)
499			if err != nil {
500				return plumbing.ZeroHash, stats, err
501			}
502			rootEntries["tasks"] = object.TreeEntry{Name: "tasks", Mode: filemode.Dir, Hash: tasksHash}
503		}
504	
505		summary := reduceBatchSummary(prepared.request.CheckpointID, existingSummary, sessionPaths, finalByID, &stats)
506		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
507		if err != nil {
508			return plumbing.ZeroHash, stats, fmt.Errorf("marshal checkpoint summary: %w", err)
509		}
510		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
511		if err != nil {
512			return plumbing.ZeroHash, stats, fmt.Errorf("create checkpoint summary blob: %w", err)
513		}
514		rootEntries[paths.MetadataFileName] = object.TreeEntry{
515			Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataHash,
516		}
517	
518		rootHash, err := storeTreeEntryMap(s.repo, rootEntries)
519		if err != nil {
520			return plumbing.ZeroHash, stats, fmt.Errorf("store checkpoint root tree: %w", err)
521		}
522		return rootHash, stats, nil
523	}
