525	func (s *treeWriter) readSessionMetadataFromSubtree(hash plumbing.Hash, stats *batchBuildStats) (*Metadata, error) {
526		tree, err := s.repo.TreeObject(hash)
527		if err != nil {
528			return nil, fmt.Errorf("read session subtree: %w", err)
529		}
530		for _, entry := range tree.Entries {
531			stats.SessionEntriesVisited++
532			if entry.Name == paths.MetadataFileName && entry.Mode != filemode.Dir {
533				stats.ExistingMetadataRead++
534				return s.readMetadataFromBlob(entry.Hash)
535			}
536		}
537		return nil, errors.New("metadata.json not found")
538	}
