540	func (s *treeWriter) mergePreparedTasks(
541		rootEntries map[string]object.TreeEntry,
542		prepared map[string]plumbing.Hash,
543		stats *batchBuildStats,
544	) (plumbing.Hash, error) {
545		taskEntries := make(map[string]object.TreeEntry)
546		if existing, ok := rootEntries["tasks"]; ok {
547			if existing.Mode != filemode.Dir {
548				return plumbing.ZeroHash, errors.New("existing tasks entry is not a directory")
549			}
550			tree, err := s.repo.TreeObject(existing.Hash)
551			if err != nil {
552				return plumbing.ZeroHash, fmt.Errorf("read existing tasks tree: %w", err)
553			}
554			for _, entry := range tree.Entries {
555				stats.TaskEntriesVisited++
556				taskEntries[entry.Name] = entry
557			}
558		}
559		for toolUseID, hash := range prepared {
560			taskEntries[toolUseID] = object.TreeEntry{Name: toolUseID, Mode: filemode.Dir, Hash: hash}
561		}
562		return storeTreeEntryMap(s.repo, taskEntries)
563	}
