565	func reduceBatchSummary(
566		checkpointID id.CheckpointID,
567		existing *CheckpointSummary,
568		sessionPaths []SessionFilePaths,
569		finalByID map[string]finalBatchSession,
570		stats *batchBuildStats,
571	) *CheckpointSummary {
572		orderedIDs := make([]string, 0, len(finalByID))
573		for sessionID := range finalByID {
574			orderedIDs = append(orderedIDs, sessionID)
575		}
576		sort.Strings(orderedIDs)
577	
578		summary := &CheckpointSummary{
579			CheckpointID: checkpointID,
580			CLIVersion:   versioninfo.Version,
581			Sessions:     sessionPaths,
582		}
583		if existing != nil {
584			summary.CommitSHA = existing.CommitSHA
585			summary.CombinedAttribution = existing.CombinedAttribution
586			summary.HasReview = existing.HasReview
587			summary.HasInvestigation = existing.HasInvestigation
588			summary.Imported = existing.Imported
589		}
590		files := make(map[string]struct{})
591		for _, sessionID := range orderedIDs {
592			stats.FinalSessionContributions++
593			final := finalByID[sessionID]
594			metadata := final.metadata
595			summary.Strategy = metadata.Strategy
596			summary.Branch = metadata.Branch
597			if metadata.CommitSHA != "" {
598				summary.CommitSHA = metadata.CommitSHA
599			}
600			summary.CheckpointsCount += metadata.CheckpointsCount
601			summary.TokenUsage = types.AddTokenUsage(summary.TokenUsage, metadata.TokenUsage)
602			summary.HasReview = summary.HasReview || final.hasReview
603			summary.HasInvestigation = summary.HasInvestigation || final.hasInvestigation
604			summary.Imported = summary.Imported || final.imported
605			for _, file := range metadata.FilesTouched {
606				files[filepath.ToSlash(file)] = struct{}{}
607			}
608		}
609		if len(files) > 0 {
610			summary.FilesTouched = make([]string, 0, len(files))
611			for file := range files {
612				summary.FilesTouched = append(summary.FilesTouched, file)
613			}
614			sort.Strings(summary.FilesTouched)
615		}
616		return summary
617	}
