1027	// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
1028	// The summary is generated from the scoped transcript (only this checkpoint's portion),
1029	// not the entire session transcript.
1030	//
1031	// summaryTimeoutSeconds is the per-invocation --summary-timeout-seconds flag
1032	// value (0 = unset). Effective precedence for the deadline: flag > settings >
1033	// no deadline. See resolveSummaryTimeout for the resolution.
1034	func generateCheckpointSummary(ctx context.Context, w, errW io.Writer, store checkpoint.Writer, checkpointID id.CheckpointID, cpSummary *checkpoint.CheckpointSummary, content *checkpoint.SessionContent, force bool, summaryTimeoutSeconds int) error {
1035		// Check if summary already exists
1036		if content.Metadata.Summary != nil && !force {
1037			return renderExplainFailure(errW, "Summary already exists", []explainRow{
1038				{Label: "id", Value: checkpointID.String()},
1039				{Label: "try", Value: fmt.Sprintf("entire checkpoint explain --generate --force %s", checkpointID)},
1040			}, fmt.Errorf("checkpoint %s already has a summary", checkpointID))
1041		}
1042	
1043		// Check if transcript exists
1044		if len(content.Transcript) == 0 {
1045			return renderExplainFailure(errW, "Checkpoint has no transcript", []explainRow{
1046				{Label: "id", Value: checkpointID.String()},
1047			}, fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID))
1048		}
1049	
1050		// Scope the transcript to only this checkpoint's portion
1051		scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, content.Metadata.GetTranscriptStart(), content.Metadata.Agent)
1052		if len(scopedTranscript) == 0 {
1053			return renderExplainFailure(errW, "Checkpoint has no transcript content (scoped)", []explainRow{
1054				{Label: "id", Value: checkpointID.String()},
1055			}, fmt.Errorf("checkpoint %s has no transcript content for this checkpoint (scoped)", checkpointID))
1056		}
1057		provider, err := resolveCheckpointSummaryProvider(ctx, w)
1058		if err != nil {
1059			return fmt.Errorf("failed to resolve summary provider: %w", err)
1060		}
1061		scopedTranscript = maybeCompactExternalTranscript(ctx, scopedTranscript, content.Metadata.Agent)
1062	
1063		// Generate summary using shared helper
1064		logging.Info(ctx, "generating checkpoint summary")
1065		if errW != nil {
1066			fmt.Fprintf(errW, "Generating checkpoint summary... (transcript: %s, provider: %s)\n",
1067				humanizeBytes(len(scopedTranscript)), provider.Name)
1068		}
1069	
1070		timeout := resolveSummaryTimeout(ctx, summaryTimeoutSeconds)
1071	
1072		attempt := newSummaryAttempt(provider.Name, timeout)
1073		// Set streaming eagerly from the provider's capability rather than waiting
1074		// for the first progress event: a streaming provider that stalls before
1075		// emitting anything should still get the streaming timeout diagnostic
1076		// ("never sent its request"), not "provider produced no output".
1077		attempt.streaming = provider.Streaming
1078		progressWriter := newSummaryProgressWriter(errW, attempt)
1079	
1080		start := time.Now()
1081		summary, err := generateCheckpointAISummary(
1082			ctx, scopedTranscript, cpSummary.FilesTouched,
1083			content.Metadata.Agent, provider.Generator,
1084			timeout, progressWriter.handle, attempt,
1085		)
1086		if err != nil {
1087			progressWriter.Flush()
1088			label, rows, structured := formatCheckpointSummaryError(err, attempt)
1089			styles := newStatusStyles(errW)
1090			fmt.Fprint(errW, styles.renderFailure(label, rows))
1091			return NewSilentError(structured)
1092		}
1093		elapsed := time.Since(start)
1094	
1095		if err := store.Write(ctx, checkpoint.SessionSummary{
1096			CheckpointID: checkpointID,
1097			SessionID:    content.Metadata.SessionID,
1098			Summary:      summary,
1099		}); err != nil {
1100			return fmt.Errorf("failed to save summary: %w", err)
1101		}
1102	
1103		styles := newStatusStyles(w)
1104		rows := summaryProviderRows(provider)
1105		rows = append(rows, explainRow{Label: "duration", Value: formatSummaryDuration(elapsed)})
1106		fmt.Fprint(w, styles.renderSuccess(fmt.Sprintf("Summary generated for %s", checkpointID), rows))
1107		return nil
1108	}
